//! Purpose-specific original questions for generation, never PolicyInputs.
//! No AST/model/index copy, source-role promotion or cached operation control.
use crate::{reactive_global_source::{Source,Body,Callable,SelectedCallable},captured_generator_budget::Budget,reactive_reads_native::Failure,reactive_raw_policy_pages::RawPolicyPages};
use std::{io,path::Path,sync::Arc};use dm_ir::SymbolId;
pub(crate) struct GenerationSource<'a>{questions:&'a dm_tree::frontend::GenerationNativeQuestions,pages:&'a dyn RawPolicyPages,root:&'a Path,order:&'a std::collections::HashMap<String,usize>,budget:&'a Arc<Budget>,operation_budget:&'a Arc<Budget>,poll:&'a dyn Fn()->io::Result<()>,profile:dm_ir::PackedU128,proof:dm_tree::checker_builtins::ValidatedCheckerProfile<'a>,path_work_peak:std::cell::Cell<usize>}
fn admit_original_path_work(budget:&Budget,previous:&std::cell::Cell<usize>,width:usize)->Result<(),Failure>{let peak=width.checked_mul(128).and_then(|n|n.checked_add(8192)).ok_or_else(||oom(budget,"generation path work geometry overflow"))?;let old=previous.get();if peak>old{budget.charge(peak-old).map_err(|message|oom(budget,message))?;previous.set(peak);}Ok(())}
fn original_path_equal(actual:&Path,requested:&Path)->bool{actual==requested||dm_preprocess::regions::relative_filesystem_path(actual,requested).is_some_and(|relative|relative.as_os_str().is_empty())}
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
impl<'a> GenerationSource<'a>{
 pub(crate) fn new(questions:&'a dm_tree::frontend::GenerationNativeQuestions,pages:&'a dyn RawPolicyPages,root:&'a Path,order:&'a std::collections::HashMap<String,usize>,budget:&'a Arc<Budget>,operation_budget:&'a Arc<Budget>,poll:&'a dyn Fn()->io::Result<()>)->Result<Self,Failure>{
  if !root.is_absolute(){return Err("generation reactive root must be absolute".into())}if pages.generation_questions().is_none_or(|issued|!std::ptr::eq(issued,questions)){return Err("generation reactive source differs from actual original reader".into())}
  let profile=questions.tree().checker_builtin_profile().ok_or("generation reactive builtin profile absent")?;let proof=questions.tree().validated_checker_profile(profile).map_err(|e|Failure::Unsupported(format!("{e:?}")))?;let value=Self{questions,pages,root,budget,operation_budget,poll,profile,proof,order,path_work_peak:std::cell::Cell::new(0)};value.require()?;Ok(value)
 }

 fn admit_path_work(&self,width:usize)->Result<(),Failure>{self.require()?;admit_original_path_work(self.operation_budget,&self.path_work_peak,width)}
 fn original_relative_file(&self,path:&Path)->Result<String,Failure>{
  self.require()?;self.admit_path_work(path.as_os_str().len().checked_add(self.root.as_os_str().len()).ok_or_else(||oom(self.operation_budget,"generation relative path width overflow"))?)?;
  // Report projection only: callers already hold the actual original member /
  // callable provenance. This pure comparison grants no source acquisition.
  let relative=dm_preprocess::regions::relative_filesystem_path(path,self.root).ok_or_else(||Failure::Unsupported(format!("generation original source {} is outside diagnostic root {}",path.display(),self.root.display())))?;let text=relative.to_str().ok_or("generation diagnostic source path not UTF8")?;self.reserve(text.len().checked_mul(4).and_then(|n|n.checked_add(512)))?;let result=text.replace('\\',"/");self.require()?;Ok(result)
 }
 fn original_lookup_path(&self,path:&Path,poll:&mut dyn FnMut()->Result<(),Failure>)->Result<Option<&Path>,Failure>{
  self.require()?;self.admit_path_work(path.as_os_str().len().checked_add(self.root.as_os_str().len()).ok_or_else(||oom(self.operation_budget,"generation relative path width overflow"))?)?;let mut selected:Option<&Path>=None;
  for(candidate,lease)in self.questions.original_sources(){self.require()?;poll()?;self.admit_path_work(candidate.as_os_str().len().checked_add(path.as_os_str().len()).ok_or_else(||oom(self.operation_budget,"generation lookup path width overflow"))?)?;let equal=original_path_equal(candidate,path);if !equal{continue}if lease.is_none()||self.questions.file_id_for_path(candidate).is_none(){return Err("generation source lookup has no actual captured original identity".into())}if selected.is_some_and(|old|old!=candidate){return Err("generation original source lookup is ambiguous".into())}selected=Some(candidate);}
  poll()?;self.require()?;Ok(selected)
 }

 fn present(&self,path:&str)->Result<bool,Failure>{self.questions.tree().checker_source_type_presence_validated(self.profile,path,&self.proof).map_err(|e|Failure::Unsupported(format!("{e:?}")))}
 fn reserve(&self,bytes:Option<usize>)->Result<(),Failure>{let bytes=bytes.ok_or_else(||oom(self.budget,"generation reactive allocation overflow"))?;self.budget.charge(bytes).map_err(|m|oom(self.budget,m))}
 fn parent<'s>(&'s self,path:&str)->Result<Option<&'s str>,Failure>{self.require()?;let tree=self.tree();let Some(owner)=tree.lookup_type(SymbolId::of(path))else{if self.present(path)?{return Err("generation positive type lacks original parent graph".into())}return Ok(None)};let Some(parent)=tree.parent(owner)else{return Ok(None)};Ok(Some(tree.type_node(parent).and_then(|n|tree.symbols().text(n.path)).ok_or("generation parent original spelling absent")?))}
 fn formal_ordinal(&self,formal:dm_tree::MemberId)->Result<dm_tree::OccurrenceId,Failure>{
  self.require()?;self.questions.member_first_original_occurrence(formal)?.ok_or_else(||Failure::from("generation formal original occurrence unavailable"))
 }
 fn variable_projected(&self,owner:&str,name:&str,full:bool)->Result<Option<crate::reactive_original_source::ReadVariable<'_>>,Failure>{
  self.require()?;if !self.present(owner)?{return Ok(None)}let tree=self.tree();let Some(fact)=dm_analysis::checker_variable_facts::variable_original_validated(tree,&self.proof,self.profile,SymbolId::of(owner),SymbolId::of(name))?else{return Ok(None)};
  let mut file=None;let value=if let Some(formal)=fact.formal{
   let width=[fact.metadata.declared_type(),fact.metadata.list_element_type(),fact.metadata.array.as_ref().and_then(|a|a.element_type)].into_iter().flatten().try_fold(0usize,|n,id|tree.symbols().text(id).and_then(|s|n.checked_add(s.len())));self.reserve(width.and_then(|n|n.checked_mul(64)).and_then(|n|n.checked_add(4096)))?;
   let ordinal=self.formal_ordinal(formal)?;if full{let point=self.questions.variable_source_point_original_at(formal,ordinal,self.profile,&self.proof)?;file=Some(std::borrow::Cow::Owned(self.original_relative_file(point.path)?));}let properties=self.questions.variable_properties_original_at(formal,ordinal,self.profile,&self.proof)?;properties.declared_hint().unwrap_or("").to_owned()
  }else{let declared=fact.metadata.declared_type().and_then(|id|tree.symbols().text(id)).unwrap_or("");let element=fact.metadata.list_element_type().and_then(|id|tree.symbols().text(id));self.reserve(declared.len().checked_add(element.map_or(0,str::len)).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(512)))?;match element{Some(element)if declared=="/list"=>format!("/list{element}"),Some(_)=>return Err("generation builtin list-element owner inconsistent".into()),None=>declared.to_owned()}};self.require()?;Ok(Some(crate::reactive_original_source::ReadVariable{owner:tree.symbols().text(fact.owner).ok_or("generation original variable owner spelling absent")?,declared:value,file,is_static:fact.metadata.flags&1!=0,is_const:fact.metadata.flags&2!=0,is_tmp:fact.metadata.flags&4!=0}))
 }
 fn callable_identity(&self,identity:dm_ir::ProcedureIdentity)->Result<Callable<'_>,Failure>{let tree=self.tree();for(ordinal,body)in self.questions.bodies().iter().enumerate(){self.require()?;let node=tree.member(body.member).ok_or("generation callable original member unavailable")?;let owner=tree.type_node(node.owner).ok_or("generation callable original owner unavailable")?.path;let verb=match node.kind{dm_tree::MemberKind::Proc=>false,dm_tree::MemberKind::Verb=>true,_=>return Err("generation noncallable in actual body roster".into())};let occurrence=tree.member_occurrence(body.member).ok_or("generation original occurrence unavailable")?;if identity== (dm_ir::ProcedureIdentity{owner,name:node.name,verb,occurrence}){return Ok(Callable{owner:tree.symbols().text(owner).ok_or("generation callable owner spelling absent")?,name:tree.symbols().text(node.name).ok_or("generation callable name spelling absent")?,ordinal,member:body.member,header:{let(_,point)=self.questions.callable_original_header(body.member)?;self.questions.original_analyze_display_line(&point)?}})}}Err("generation selected callable lacks actual original body occurrence".into())}

}
impl Source for GenerationSource<'_>{
 fn dependency_marker_rows(&self,poll:&mut dyn FnMut()->io::Result<()>)->Result<crate::captured_marker_rows::Rows<'_>,Failure>{crate::reactive_raw_policy_pages::collect_marker_rows(|visit|self.pages.for_each(visit),self.order,self.budget,&["READS_AS","PROC_SUMMARY","READ_LOOKUP","CAPABILITY_TYPE","CAPABILITY_DEF","cap_keys","SYSTEM_ACCESSOR","READS_FROM","CAPABILITIES","STAT"],true,true,true,poll,&||self.require())}

 fn member_has_source(&self,member:dm_tree::MemberId)->Result<bool,Failure>{self.require()?;self.questions.member_has_original_source(member).map_err(Failure::from)}
 fn with_header_line(&self,member:dm_tree::MemberId,consume:&mut dyn FnMut(&str,usize,&str)->Result<(),Failure>)->Result<(),Failure>{self.require()?;let (ordinal,point)=self.questions.callable_original_header(member)?;let display=self.questions.original_analyze_display_line(&point)?;let name=self.tree().member(member).and_then(|node|self.tree().symbols().text(node.name)).ok_or("generation callable original name absent")?;self.pages.with_callable_file(ordinal,name,&mut|relative,views|{let raw=views.raw()?;let line=raw.lines().nth(display.saturating_sub(1)).ok_or("generation setter raw original header absent")?;consume(relative,display,line)})?;self.require()}

 fn with_policy_files(&self,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{self.require()?;let result=self.pages.for_each(visit);if matches!(&result,Err(Failure::Operational(_))){return result}self.require()?;result}

 fn occurrences(&self)->&[dm_tree::frontend::BodyOccurrence]{self.questions.bodies()}
 fn raw_body_text(&self,ordinal:usize)->Result<&str,Failure>{self.questions.body_source_text(ordinal).map_err(Failure::from)}
 fn callable(&self,owner:&str,name:&str)->Result<SelectedCallable<'_>,Failure>{self.require()?;if !self.present(owner)?{return Ok(SelectedCallable::Missing)}let tree=self.tree();self.reserve(self.body_count().checked_mul(std::mem::size_of::<dm_ir::ResolvedMeaning>()*16).and_then(|n|n.checked_add(tree.types().len().checked_mul(std::mem::size_of::<SymbolId>()*16)?)).and_then(|n|n.checked_add(8192)))?;Ok(match dm_analysis::checker_call_facts::callable_any(tree,tree,self.profile,SymbolId::of(owner),SymbolId::of(name))?{dm_analysis::checker_call_facts::CallableFact::Source{identity,..}=>SelectedCallable::Source(self.callable_identity(identity)?),dm_analysis::checker_call_facts::CallableFact::CheckerBuiltin{..}=>SelectedCallable::Builtin,dm_analysis::checker_call_facts::CallableFact::Missing=>SelectedCallable::Missing})}
 fn parent_callable(&self,ordinal:usize)->Result<Option<Callable<'_>>,Failure>{self.require()?;let body=self.questions.bodies().get(ordinal).ok_or("generation parent caller occurrence absent")?;match dm_analysis::checks_parent_call::source_predecessor_in_profile(self.tree(),body.member,self.tree(),self.profile)?{dm_analysis::checks_parent_call::SourcePredecessorProjection::Source(identity)=>self.callable_identity(identity).map(Some),dm_analysis::checks_parent_call::SourcePredecessorProjection::NoParent|dm_analysis::checks_parent_call::SourcePredecessorProjection::BuiltinBoundary=>Ok(None)}}
 fn visit_overrides<'source>(&'source self,receiver:&str,name:&str,poll:&mut dyn FnMut()->Result<(),Failure>,emit:&mut dyn FnMut(Callable<'source>)->Result<(),Failure>)->Result<(),Failure>{self.require()?;let tree=self.tree();self.reserve(tree.types().len().checked_mul(std::mem::size_of::<&str>()*4).and_then(|n|n.checked_add(1024)))?;let mut owners=Vec::new();owners.try_reserve_exact(tree.types().len()).map_err(|e|oom(self.budget,e.to_string()))?;for node in tree.types(){poll()?;let owner=tree.symbols().text(node.path).ok_or("generation override owner spelling absent")?;if self.is_subtype(owner,receiver)?&&self.own_callable_exists(owner,name)?{owners.push(owner)}}owners.sort_unstable();owners.dedup();for owner in owners{poll()?;if let SelectedCallable::Source(call)=self.callable(owner,name)?{emit(call)?;}}poll()?;self.require()}
 fn site(&self,ordinal:usize,offset:usize)->Result<(String,u32),Failure>{let line=self.line_at(offset)?;self.site_line(ordinal,line)}
 fn site_line(&self,ordinal:usize,line:u32)->Result<(String,u32),Failure>{Ok((self.relative_body_file(ordinal)?,line))}
 fn line_at(&self,offset:usize)->Result<u32,Failure>{self.require()?;let point=self.questions.original_note_point(offset)?;u32::try_from(point.line).map_err(|_|Failure::from("generation source line overflow"))}
 fn parent_type(&self,owner:&str)->Result<Option<&str>,Failure>{self.parent(owner)}
 fn own_callable_exists(&self,owner:&str,name:&str)->Result<bool,Failure>{self.require()?;if !self.present(owner)?{return Ok(false)}let tree=self.tree();let owner=SymbolId::of(owner);let name=SymbolId::of(name);let id=tree.lookup_type(owner).ok_or("generation positive callable owner absent")?;for member in tree.type_node(id).ok_or("generation callable owner absent")?.members.iter(){self.require()?;let node=tree.member(*member).ok_or("generation own callable member absent")?;if node.name==name&&matches!(node.kind,dm_tree::MemberKind::Proc|dm_tree::MemberKind::Verb){return Ok(true)}}use dm_ir::{Resolver,ResolveQuery as Q,ResolvedMeaning as M};for verb in[false,true]{match Resolver::resolve(tree,Q::CheckerBuiltinProc{profile:self.profile,owner,name,verb}){M::Missing=>(),M::Member{owner:declared,data,..}=>{if data.procedure.is_none()||data.inherited_opaque().is_some(){return Err("generation own builtin callable unissued".into())}if declared==owner{return Ok(true)}},_=>return Err("generation builtin callable presence unissued".into())}}Ok(false)}
 fn plans_marker_rows(&self)->Result<crate::captured_marker_rows::Rows<'_>,Failure>{crate::reactive_raw_policy_pages::collect_marker_rows(|visit|self.pages.for_each(visit),self.order,self.budget,&["CAPABILITIES","CAPABILITY_DEF","CAPABILITY_TYPE","STATE_GRAPH","STAT"],true,true,true,&mut||self.checkpoint(),&||self.require())}
 fn with_plan_metadata_files(&self,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>,bool)->Result<bool,Failure>)->Result<bool,Failure>{self.with_policy_files(&mut|relative,views|visit(relative,views,true))}
 fn with_plan_reader_file(&self,ordinal:usize,name:&str,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>)->Result<(),Failure>)->Result<(),Failure>{self.require()?;let pending=self.pages.with_callable_file(ordinal,name,visit);if matches!(&pending,Err(Failure::Operational(_))){return pending}self.require()?;pending}
 fn has_original_body(&self,member:dm_tree::MemberId)->Result<bool,Failure>{self.require()?;let Some(ordinal)=self.questions.member_first_original_occurrence(member)?else{return Ok(false)};self.questions.find_body_ordinal_original_at(member,ordinal,&mut||self.require()).map(|ordinal|ordinal.is_some())}
 fn marker_rows(&self,poll:&mut dyn FnMut()->io::Result<()>)->Result<crate::captured_marker_rows::Rows<'_>,Failure>{crate::reactive_raw_policy_pages::collect_marker_rows(|visit|self.pages.for_each(visit),self.order,self.budget,&["READS_AS","PROC_SUMMARY","READ_LOOKUP","CAPABILITY_TYPE","CAPABILITY_DEF","cap_keys","SYSTEM_ACCESSOR","READS_FROM","CAPABILITIES","STAT"],false,false,false,poll,&||self.require())}
 fn raw_metadata(&self,poll:&mut dyn FnMut()->io::Result<()>,emit:&mut dyn FnMut(&str,crate::raw_reactive_metadata_policy::Event<'_>)->Result<(),Failure>)->Result<(),Failure>{if !self.pages.for_each(&mut|relative,views|{for line in views.marker()?.split('\n'){poll()?;self.require()?;crate::raw_reactive_metadata_policy::visit_line(line,|event|emit(relative,event))?;}Ok(true)})?{return Err("generation raw metadata traversal incomplete".into())}poll()?;self.require()}
 fn raw_width(&self)->Result<usize,Failure>{let mut width=0usize;if !self.pages.for_each(&mut|_,views|{self.require()?;width=width.checked_add(views.raw()?.len()).ok_or_else(||oom(self.budget,"generation raw width overflow"))?;Ok(true)})?{return Err("generation raw width traversal incomplete".into())}Ok(width)}
 fn definition_neighbors(&self,relative:&str,line:u32,poll:&mut dyn FnMut()->Result<(),Failure>)->Result<(Option<(usize,&str,&str)>,Option<(usize,&str,&str)>),Failure>{self.require()?;self.reserve(self.root.as_os_str().len().checked_add(relative.len()).and_then(|n|n.checked_mul(16)).and_then(|n|n.checked_add(1024)))?;let requested=self.root.join(relative);let Some(path)=self.original_lookup_path(&requested,poll)?else{poll()?;return Ok((None,None))};let mut before=None;let mut after=None;self.questions.visit_definition_points(&mut||poll(),&mut|point|{if point.path!=path{return Ok(())}let item=(point.line,point.owner,point.name);if item.0<=line as usize{if before.is_none_or(|p|p<item){before=Some(item)}}else if after.is_none_or(|p|item<p){after=Some(item)}Ok(())})?;poll()?;Ok((before,after))}

 fn tree(&self)->&dm_tree::SemanticTree{self.questions.tree()}
 fn budget(&self)->&Arc<Budget>{self.budget}
 fn operation_budget(&self)->&Arc<Budget>{self.operation_budget}
 fn checkpoint(&self)->io::Result<()>{self.budget.require().map_err(|m|io::Error::new(io::ErrorKind::OutOfMemory,m))?;(self.poll)()?;self.budget.require().map_err(|m|io::Error::new(io::ErrorKind::OutOfMemory,m))}
 fn require(&self)->Result<(),Failure>{self.budget.require().map_err(|m|oom(self.budget,m))?;(self.poll)()?;self.budget.require().map_err(|m|oom(self.budget,m))?;if self.pages.generation_questions().is_none_or(|issued|!std::ptr::eq(issued,self.questions)){return Err("generation actual question source expired or foreign".into())}Ok(())}
 fn variable_type(&self,owner:&str,name:&str)->Result<Option<String>,Failure>{Ok(self.variable_projected(owner,name,false)?.map(|value|value.declared))}
 fn variable(&self,owner:&str,name:&str)->Result<Option<crate::reactive_original_source::ReadVariable<'_>>,Failure>{self.variable_projected(owner,name,true)}
 fn receiver_variable_type(&self,owner:&str,name:&str)->Result<Option<String>,Failure>{Ok(self.variable_projected(owner,name,true)?.map(|value|value.declared))}
 fn declaring_owner<'a>(&'a self,receiver:&str,name:&str)->Result<Option<&'a str>,Failure>{
  let tree=self.tree();let bound=tree.types().len().checked_add(1).ok_or_else(||oom(self.budget,"generation original ancestry bound overflow"))?;crate::reactive_original_source::variable_declaring_owner_original(receiver,name,bound,&mut||self.require(),&mut|owner,name|{if !self.present(owner)?{return Ok(None)}let Some(fact)=dm_analysis::checker_variable_facts::variable_original_validated(tree,&self.proof,self.profile,SymbolId::of(owner),SymbolId::of(name))?else{return Ok(None)};if owner!="/"&&fact.owner==SymbolId::of("/"){return Ok(None)}Ok(Some(tree.symbols().text(fact.owner).ok_or("generation original declared owner spelling absent")?))},&mut|owner|self.parent(owner))
 }
 fn is_subtype(&self,child:&str,parent:&str)->Result<bool,Failure>{crate::reactive_original_source::subtype_original(self.tree(),child,parent,&mut||self.require(),&mut|child|self.present(child))}
 fn body_count(&self)->usize{self.questions.bodies().len()}
 fn visit_callables<'source>(&'source self,names:Option<&[&str]>,poll:&mut dyn FnMut()->Result<(),Failure>,emit:&mut dyn FnMut(Callable<'source>)->Result<(),Failure>)->Result<(),Failure>{
  let tree=self.tree();for(index,target)in tree.declarations().iter().enumerate(){poll()?;self.require()?;let dm_tree::Target::Member(member)=*target else{continue};let node=tree.member(member).ok_or("generation callable member absent")?;if !matches!(node.kind,dm_tree::MemberKind::Proc|dm_tree::MemberKind::Verb){continue}let owner=tree.type_node(node.owner).and_then(|n|tree.symbols().text(n.path)).ok_or("generation callable owner absent")?;let name=tree.symbols().text(node.name).ok_or("generation callable name absent")?;if names.is_some_and(|names|!names.contains(&name)){continue}let ordinal=self.questions.body_ordinal_original_at(member,dm_tree::OccurrenceId(u32::try_from(index).map_err(|_|oom(self.budget,"generation callable ordinal overflow"))?),&mut||self.require())?;emit(Callable{owner,name,ordinal,member,header:{let(_,point)=self.questions.callable_original_header(member)?;self.questions.original_analyze_display_line(&point)?}})?;}self.require()
 }
 fn relative_body_file(&self,ordinal:usize)->Result<String,Failure>{self.require()?;let body=self.questions.bodies().get(ordinal).ok_or("generation body ordinal unavailable")?;let(_,point)=self.questions.callable_original_header(body.member)?;self.original_relative_file(point.path)}
 fn with_body(&self,ordinal:usize,consume:&mut dyn FnMut(&dyn Body)->Result<(),Failure>)->Result<(),Failure>{
  self.require()?;let pending=self.questions.with_body_checked_using(ordinal,|input,host|host.syntax_checked(input),|body|Ok(consume(&body)));let value=match pending{Ok(value)=>value,Err(dm_tree::frontend::BodySyntaxFailure::Operational(actual))=>return Err(Failure::Operational(actual)),Err(dm_tree::frontend::BodySyntaxFailure::Syntax(error))=>Err(Failure::Unsupported(error.message))};if matches!(&value,Err(Failure::Operational(_))){return value}self.require()?;value
 }
 fn with_budget(&self,budget:&Arc<Budget>,consume:&mut dyn FnMut(&dyn Source)->Result<(),Failure>)->Result<(),Failure>{let page=GenerationSource{questions:self.questions,pages:self.pages,root:self.root,budget,operation_budget:self.operation_budget,poll:self.poll,profile:self.profile,proof:self.proof,order:self.order,path_work_peak:std::cell::Cell::new(self.path_work_peak.get())};let pending=consume(&page);self.path_work_peak.set(self.path_work_peak.get().max(page.path_work_peak.get()));pending}
}

#[cfg(test)]mod relative_original_tests{
 use super::*;
 #[test]fn original_generation_path_work_reserves_one_live_peak_across_many_bodies(){
  let budget=Budget::new(65536).unwrap();let peak=std::cell::Cell::new(0);let start=budget.used();for _ in 0..100_000{admit_original_path_work(&budget,&peak,200).unwrap();}assert_eq!(budget.used()-start,200*128+8192);admit_original_path_work(&budget,&peak,400).unwrap();assert_eq!(budget.used()-start,400*128+8192);let before=peak.get();let failure=admit_original_path_work(&budget,&peak,800).unwrap_err();assert!(matches!(failure,Failure::Operational(actual)if actual.kind()==io::ErrorKind::OutOfMemory));assert_eq!(peak.get(),before);
 }
 #[test]fn original_generation_path_projection_preserves_supported_windows_prefixes_and_exact_domain(){
  let root=Path::new("E:/original-generation-project");let ordinary=root.join("code/probe.dm");let verbatim=Path::new(r"\\?\E:\original-generation-project\code\probe.dm");
  if cfg!(windows){assert!(original_path_equal(verbatim,&ordinary));assert_eq!(dm_preprocess::regions::relative_filesystem_path(verbatim,root).unwrap(),Path::new("code/probe.dm"));}
  assert!(!original_path_equal(&root.join("code/other.dm"),&ordinary));assert!(dm_preprocess::regions::relative_filesystem_path(Path::new("E:/original-generation-project-other/code/probe.dm"),root).is_none());
 }
}
